const e="primaly-malaysia-public-speaking",c=2026,i="Read the whole competition page (categories and topics, timeline, Preliminary and Final Round, FAQ, 12-section Rules & Regulations) and the Primaly site footer. Source and web page agree except two earlier wordings: the page first showed the Category B prepared speech as 5 to 7 minutes and Category C as 6 to 8 minutes and struck them out for 4 to 6 minutes (the newer value is used). The page timeline lists 9 August 2026 as the Preliminary Round video deadline (11.59 PM) and 19 September 2026 as the Grand Final (the template Evidence calls 9 August to 19 September the Preliminary Round period; the page prints the deadline). Registration is shown as closed. Not printed: the exact Grand Final venue, a prize list or prize amounts, the number of judges, the date results are announced. The organiser's branch addresses on the site footer are not copied.",a={Title:"Rules & Criteria",Subtitle:"Primaly National Public Speaking Competition 2026, Malaysia. Read these rules before you register.",NoticeTitle:"Please Read Before Registering",Notice:"Entry is free and only for Malaysian citizens who are in a primary or secondary school in Malaysia in 2026. The Preliminary Round is an online video. Submit your video by {{PreliminaryDeadline}}. The Grand Final is on {{GrandFinalDate}} at {{Venue}}. Speak only on the official topics for your category, in English.",Notes:["Entry is limited to {{ParticipationLimit}}.","Submit your Preliminary Round video by {{PreliminaryDeadline}}.","The Grand Final is on {{GrandFinalDate}}. The top 8 of each category compete in it.","Choose one official title for your category. You use the same title in the Preliminary Round and the Grand Final.","Register through {{RegistrationLink}}. Questions: {{Contact}}."],Sections:[{Key:"general",Title:"General Rules",Items:["The competition has two stages: a Preliminary Round (online video submission) and a Grand Final (face to face in Shah Alam, Selangor).","All speeches must be in English.","Participants may only give a speech based on the official topics for their own category.","Participants must choose and deliver a speech on one of the official titles for their category. They may not change, combine or replace the official titles with their own topics.","The speech must be relevant to the chosen title. Judges may penalise speeches that go far away from the title. A speech that is not on an official topic, or that moves far from the chosen topic, can be disqualified at the organisers' discretion.","All speeches must suit a school-age audience and should be respectful, responsible and constructive.","Hate speech, discrimination, obscenity, personal attacks or offensive material is strictly not allowed.","Speeches must be original. Plagiarism, including copying a large part from books, websites, articles, speeches or other sources, is not allowed and can lead to immediate disqualification.","Artificial Intelligence (AI) tools can be used for brainstorming, research, improving language or generating ideas. The participant must own and understand the speech and deliver it in a real way. Speeches that are fully written by AI are not encouraged and can affect the evaluation.","The organisers can investigate and disqualify any participant whose speech is copied, fully written by others, or not the participant's own work and ability.","The organisers can reject or disqualify any speech that is inappropriate, defamatory, unlawful, or not in line with the aims of the competition.","The organisers can change these rules where needed.","The organisers can postpone, change, suspend or cancel any stage of the competition because of events they could not foresee.","In all matters about the competition, the organisers' decision is final."]},{Key:"eligibility",Title:"Eligibility",Items:["The competition is open only to Malaysian citizens.","Participants must be enrolled in a primary or secondary educational institution in Malaysia in 2026.","Category A: 10 to 12 years old. Category B: 13 to 15 years old. Category C: 16 to 17 years old.","A participant must compete in the category for his or her age as at 31 December 2026.","Immediate family members of employees of Bravometer Sdn. Bhd. cannot take part.","Registration cannot be transferred to another person.","False, wrong or misleading information can lead to immediate disqualification. The organisers can check participant information at any stage."]},{Key:"dates",Title:"Important Dates",Items:["Preliminary Round (video submission): submit your video by {{PreliminaryDeadline}}.","Grand Final (face to face in Shah Alam, Selangor): {{GrandFinalDate}}.","Registration status on the competition page: {{RegistrationStatus}}."]},{Key:"venue",Title:"Venue",Items:["The Grand Final is held at {{Venue}}.","Finalists must attend the Grand Final in person at the venue given by the organisers."]},{Key:"registration",Title:"How to Register",Items:["Complete the official registration process before the stated deadline. Register through {{RegistrationLink}}.","Entry is limited to {{ParticipationLimit}}.","Participation is free of charge.","Record and upload your speech video as the organisers instruct when you register.","Late video submissions are not accepted. Participants are responsible for submitting their videos before the deadline.","Each participant can submit only one speech video. If a participant sends more than one, only the first video received is accepted and judged. Later videos are not considered.","A video that does not follow the competition rules can be penalised, rejected or disqualified at the organisers' discretion.","The prepared speech titles for each category are announced at the launch of the competition. Each participant picks one title from the list for his or her category and uses the same title for the Preliminary Round and the Grand Final.","Impromptu speech topics are not announced in advance. They are revealed in the Grand Final.","Finalists are contacted by the email address and/or phone number given at registration. Results can also be announced through the official competition channels."]},{Key:"fees",Title:"Fees",Items:["There is no registration fee. Participation is completely free of charge.","A physical certificate costs {{PhysicalCertificateFee}}. The e-certificate is free.","Finalists pay their own travel and accommodation costs for the Grand Final."]},{Key:"levels",Title:"Rounds and Qualification",Items:["Round 1, Preliminary Round: each participant sends a recorded video of a prepared speech.","Round 2, Grand Final: the top 8 participants of each category go to the Grand Final. Each finalist gives a prepared speech and an impromptu speech.","If a finalist cannot attend, participants ranked 9th and below are contacted to take the place.","A finalist who does not attend the Grand Final loses his or her place.","Finalists must attend the Grand Final in person."]},{Key:"judging",Title:"Judging",Items:["Speeches are judged on Content, Delivery, Clarity and Relevance, in both the Preliminary Round and the Grand Final.","Judges can also consider audience engagement, language skill and how well the speaker communicates overall.","All judging decisions are final and binding.","Scores and judges' comments may not be shown.","Appeals and disputes about the results are not accepted."]},{Key:"prizes",Title:"Awards and Certificates",Items:["Winners receive trophies, certificates and prizes as decided by the organisers.","Participants who meet the participation requirements set by the organisers receive a certificate of participation. Certificates are only given to those who meet the requirements.","The e-certificate is free: {{CertificateEligibility}}. A physical certificate costs {{PhysicalCertificateFee}}.","Prizes cannot be transferred or exchanged."]},{Key:"conduct",Title:"Conduct",Items:["Participants must behave respectfully at all times.","Unsporting conduct, disruptive behaviour, cheating or trying to influence the judges can lead to disqualification.","During the impromptu speech, participants may not get help from parents, teachers, coaches or anyone else."]},{Key:"other",Title:"Other Information",Items:["By taking part, participants and their parents or guardians agree to photography, video and audio recording at all stages of the competition.","The organisers can use participants' names, photographs, video recordings, speeches and competition materials for promotion, education, publicity and reporting without extra payment. This can include websites, social media, printed materials, news and future promotions.","Participants and their parents or guardians agree that personal data is collected, processed and stored for running the competition. It is handled under Malaysian data protection laws. Limited participant information can be shared with official partners, sponsors and collaborators only for the competition.","The competition is endorsed by the Ministry of Education Malaysia (KPM) and run by Auxicon-world as organiser.","Updates are posted on the competition's Telegram channel: {{TelegramChannel}}."]}],Documents:[{Title:"Primaly National Public Speaking Competition 2026",Url:"https://primaly.edu.my/primaly-national-public-speaking-competition-2026"},{Title:"Primaly Terms and Conditions",Url:"https://primaly.edu.my/wpautoterms/terms-and-conditions"},{Title:"Primaly Privacy Policy",Url:"https://primaly.edu.my/wpautoterms/privacy-policy"}]},t=[],n=[{AgeGroup:"Category A",Source:"Primaly National Public Speaking Competition 2026 page (primaly.edu.my), Category & Topics; Primaly National Public Speaking Competition 2026 page (primaly.edu.my), Rules & Regulations 1.3",Sections:{About:null,TimeAndFormat:["Prepared speech in the Grand Final: 4 to 6 minutes."],Rules:["Ages 10 to 12. Choose one of these titles: My Superpower for Staying Safe Online; Think Before You Click!; Can AI Be My Homework Helper?; Are Video Games Good for Kids?; One Kind Message Can Change Everything; What Would Happen If the Internet Had No Rules; Playing Smart in the World of E-Games; Should Children Spend More Time Online or Offline; Together Against Cyberbullying; If I Could Invent a Safer Internet."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Time and format
- Prepared speech in the Grand Final: 4 to 6 minutes.

## Rules
- Ages 10 to 12. Choose one of these titles: My Superpower for Staying Safe Online; Think Before You Click!; Can AI Be My Homework Helper?; Are Video Games Good for Kids?; One Kind Message Can Change Everything; What Would Happen If the Internet Had No Rules; Playing Smart in the World of E-Games; Should Children Spend More Time Online or Offline; Together Against Cyberbullying; If I Could Invent a Safer Internet.`},{AgeGroup:"Category B",Source:"Primaly National Public Speaking Competition 2026 page (primaly.edu.my), Category & Topics; Primaly National Public Speaking Competition 2026 page (primaly.edu.my), Rules & Regulations 1.3, 5.4",Sections:{About:null,TimeAndFormat:["Prepared speech in the Grand Final: 4 to 6 minutes. The page first showed 5 to 7 minutes and corrected it to 4 to 6 minutes."],Rules:["Ages 13 to 15. Choose one of these titles: Is Artificial Intelligence Making Us Smarter or Lazier; Should Influencers Be Role Models?; Winning Online: Skill, Strategy, or Screen Time?; The Internet Never Forgets, Should We Be More Careful?; Cyberbullying: A Joke or a Serious Problem?; Can AI Replace Human Creativity?; What Makes Someone Worth Following Online?; Should Schools Teach Digital Citizenship?; E-Games: The Sport of the Future?; Behind Every Screen Is a Real Person."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Time and format
- Prepared speech in the Grand Final: 4 to 6 minutes. The page first showed 5 to 7 minutes and corrected it to 4 to 6 minutes.

## Rules
- Ages 13 to 15. Choose one of these titles: Is Artificial Intelligence Making Us Smarter or Lazier; Should Influencers Be Role Models?; Winning Online: Skill, Strategy, or Screen Time?; The Internet Never Forgets, Should We Be More Careful?; Cyberbullying: A Joke or a Serious Problem?; Can AI Replace Human Creativity?; What Makes Someone Worth Following Online?; Should Schools Teach Digital Citizenship?; E-Games: The Sport of the Future?; Behind Every Screen Is a Real Person.`},{AgeGroup:"Category C",Source:"Primaly National Public Speaking Competition 2026 page (primaly.edu.my), Category & Topics; Primaly National Public Speaking Competition 2026 page (primaly.edu.my), Rules & Regulations 1.3, 5.4",Sections:{About:null,TimeAndFormat:["Prepared speech in the Grand Final: 4 to 6 minutes. The page first showed 6 to 8 minutes and corrected it to 4 to 6 minutes."],Rules:["Ages 16 to 17. Choose one of these titles: Artificial Intelligence: Tool, Threat, or Teammate?; Has Social Media Connected Us or Divided Us?; A Digital World for All Abilities; Should Influencers Be Held Accountable for Their Content?; The Price of Going Viral; E-Games and Traditional Sports: Rivals or Partners?; Freedom of Expression vs Online Safety; The Bystander's Role in Cyberbullying; Digital Inclusion Beyond Physical Disabilities; Safety, Fairness, and Fun: Finding Balance in E-Games."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Time and format
- Prepared speech in the Grand Final: 4 to 6 minutes. The page first showed 6 to 8 minutes and corrected it to 4 to 6 minutes.

## Rules
- Ages 16 to 17. Choose one of these titles: Artificial Intelligence: Tool, Threat, or Teammate?; Has Social Media Connected Us or Divided Us?; A Digital World for All Abilities; Should Influencers Be Held Accountable for Their Content?; The Price of Going Viral; E-Games and Traditional Sports: Rivals or Partners?; Freedom of Expression vs Online Safety; The Bystander's Role in Cyberbullying; Digital Inclusion Beyond Physical Disabilities; Safety, Fairness, and Fun: Finding Balance in E-Games.`}],o=[{Title:"Prepared Speech",Source:"Primaly National Public Speaking Competition 2026 page (primaly.edu.my), Preliminary Round and Final Round; Primaly National Public Speaking Competition 2026 page (primaly.edu.my), Rules & Regulations 4, 5.4, 6; Primaly National Public Speaking Competition 2026 page (primaly.edu.my), FAQ",Sections:{About:["Preliminary Round: a recorded video of an original speech on one of the official titles for your category.","Grand Final: the 8 finalists of each category give the prepared speech again, on the same title chosen for the Preliminary Round."],TimeAndFormat:["Preliminary Round video: 3 minutes.","Grand Final prepared speech: 4 to 6 minutes in all three categories."],Rules:["The video must be original and must clearly show the participant's face and body from the waist up throughout the speech.","The camera is at eye level and the speaker is fully visible for the whole speech.","The voice must be clear and easy to hear for the whole recording.","The video must be in English."],Allowed:["Basic editing such as trimming the beginning or the end of the video."],NotAllowed:["Cuts during the speech, filters, voice enhancement, dubbing, special effects or any edit that changes the speech performance.","Costumes, slides or visual aids, unless the organisers say otherwise."],Judging:["Content, Delivery, Clarity and Relevance."],Points:null,Notes:null},Markdown:`## About this competition
- Preliminary Round: a recorded video of an original speech on one of the official titles for your category.
- Grand Final: the 8 finalists of each category give the prepared speech again, on the same title chosen for the Preliminary Round.

## Time and format
- Preliminary Round video: 3 minutes.
- Grand Final prepared speech: 4 to 6 minutes in all three categories.

## Rules
- The video must be original and must clearly show the participant's face and body from the waist up throughout the speech.
- The camera is at eye level and the speaker is fully visible for the whole speech.
- The voice must be clear and easy to hear for the whole recording.
- The video must be in English.

## Allowed
- Basic editing such as trimming the beginning or the end of the video.

## Not allowed
- Cuts during the speech, filters, voice enhancement, dubbing, special effects or any edit that changes the speech performance.
- Costumes, slides or visual aids, unless the organisers say otherwise.

## Judging
- Content, Delivery, Clarity and Relevance.`},{Title:"Impromptu Speech",Source:"Primaly National Public Speaking Competition 2026 page (primaly.edu.my), Final Round; Primaly National Public Speaking Competition 2026 page (primaly.edu.my), Rules & Regulations 5.5, 8.3; Primaly National Public Speaking Competition 2026 page (primaly.edu.my), FAQ",Sections:{About:["Grand Final only. A short speech on a title that is given to the finalists on stage. Specific titles are given on stage. The theme for 2026 is {{ImpromptuTheme}}."],TimeAndFormat:["Preparation time: 1 minute, on stage.","Speaking time: at least 1 minute and at most 2 minutes, in all categories."],Rules:["The topic is not announced in advance."],Allowed:null,NotAllowed:["Help from parents, teachers, coaches or any other person during the impromptu speech."],Judging:["Content, Delivery, Clarity and Relevance."],Points:null,Notes:null},Markdown:`## About this competition
- Grand Final only. A short speech on a title that is given to the finalists on stage. Specific titles are given on stage. The theme for 2026 is {{ImpromptuTheme}}.

## Time and format
- Preparation time: 1 minute, on stage.
- Speaking time: at least 1 minute and at most 2 minutes, in all categories.

## Rules
- The topic is not announced in advance.

## Not allowed
- Help from parents, teachers, coaches or any other person during the impromptu speech.

## Judging
- Content, Delivery, Clarity and Relevance.`}],r=[],s=[{Key:"PreliminaryDeadline",Kind:"date",Label:"Preliminary Round video deadline",Value:"2026-08-09 11.59 PM",Source:"Primaly National Public Speaking Competition 2026 page (primaly.edu.my), Timeline"},{Key:"GrandFinalDate",Kind:"date",Label:"Grand Final",Value:"2026-09-19",Source:"Primaly National Public Speaking Competition 2026 page (primaly.edu.my), Timeline"},{Key:"RegistrationStatus",Kind:"text",Label:"Registration status printed on the page",Value:"REGISTRATION CLOSED",Source:"Primaly National Public Speaking Competition 2026 page (primaly.edu.my)"},{Key:"ParticipationLimit",Kind:"text",Label:"Limit on participation",Value:"200 participations per category",Source:"Primaly National Public Speaking Competition 2026 page (primaly.edu.my)"},{Key:"ImpromptuTheme",Kind:"text",Label:"Impromptu speech theme",Value:"Safe Internet (2026 edition)",Source:"Primaly National Public Speaking Competition 2026 page (primaly.edu.my), Final Round"},{Key:"PhysicalCertificateFee",Kind:"fee",Label:"Physical certificate (the e-certificate is free)",Value:"RM15",Source:"Primaly National Public Speaking Competition 2026 page (primaly.edu.my)"},{Key:"CertificateEligibility",Kind:"link",Label:"Check your certificate eligibility",Value:"https://datastudio.google.com/reporting/a8fb1df0-f352-40bc-b49f-cda9fe1fb16e/page/rv1uF",Source:"Primaly National Public Speaking Competition 2026 page (primaly.edu.my), Check your certificate eligibility"},{Key:"RegistrationLink",Kind:"link",Label:"Registration form",Value:"https://seminar.primaly.edu.my/order/form/pnpsc01",Source:"Primaly National Public Speaking Competition 2026 page (primaly.edu.my)"},{Key:"TelegramChannel",Kind:"link",Label:"Telegram updates channel",Value:"https://t.me/pnpsc2026",Source:"Primaly National Public Speaking Competition 2026 page (primaly.edu.my)"},{Key:"Venue",Kind:"address",Label:"Grand Final venue",Value:{Name:"Venue given by the organisers",Address:"",City:"Shah Alam, Selangor, Malaysia",MapUrl:"",Directions:"Face to face final; the exact venue is not printed on the page."},Source:"Primaly National Public Speaking Competition 2026 page (primaly.edu.my), Timeline; Primaly National Public Speaking Competition 2026 page (primaly.edu.my), Rules & Regulations 5.1"},{Key:"Contact",Kind:"contact",Label:"Competition contact",Value:{Name:"Primaly (Auxicon-world, organiser)",Role:"Competition questions on WhatsApp or email",Phone:"010-761 0228",WhatsApp:"+60 10-761 0228",Email:"inquiry@primaly.edu.my"},Source:"Primaly National Public Speaking Competition 2026 page (primaly.edu.my), WhatsApp link; Primaly contact details"}],l=[{Claim:"Categories, topics, timeline, rounds, FAQ and Rules & Regulations",SourceType:"Primary - organiser's own competition page",Source:"Primaly National Public Speaking Competition 2026 page (primaly.edu.my)",Url:"https://primaly.edu.my/primaly-national-public-speaking-competition-2026"},{Claim:"Contact numbers and email",SourceType:"Primary - organiser's own website",Source:"Primaly website footer",Url:"https://primaly.edu.my/"}],d={TemplateKey:e,Year:2026,Note:i,Page:a,ParticipantTypes:t,AgeGroups:n,Competitions:o,CompetitionAgeGroups:r,Variables:s,Evidence:l};export{n as AgeGroups,r as CompetitionAgeGroups,o as Competitions,l as Evidence,i as Note,a as Page,t as ParticipantTypes,e as TemplateKey,s as Variables,c as Year,d as default};
